interface FileDropzoneInputProps {
  label: string;
  description?: string;
  withAsterisk?: boolean;
  kind: 'image' | 'file';
  accept?: string[];
  title: string;
  hint: string;
  rejectMessage: string;
  value?: File | null;
  onChange?: (value: File | null) => void;
  error?: React.ReactNode;
  'data-path'?: string;
}

function ImagePreview({ file }: { file: File }) {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    const objectUrl = URL.createObjectURL(file);
    setUrl(objectUrl);
    return () => URL.revokeObjectURL(objectUrl);
  }, [file]);

  return url ? (
    <Image src={url} alt={`Preview of ${file.name}`} className={classes.preview} fit="cover" />
  ) : null;
}

export function FileDropzoneInput({
  label,
  description,
  withAsterisk,
  kind,
  accept,
  title,
  hint,
  rejectMessage,
  value,
  onChange,
  error,
  'data-path': dataPath,
}: FileDropzoneInputProps) {
  const field = useFormField<File | null>(onChange);
  const file = (field.subscribed ? field.value : value) ?? null;
  const [rejection, setRejection] = useState<string | null>(null);

  const handleDrop = ([dropped]: File[]) => {
    setRejection(null);
    onChange?.(dropped ?? null);
  };

  const handleReject = (rejections: FileRejection[]) => {
    const tooMany = rejections.some((item) =>
      item.errors.some((rejectionError) => rejectionError.code === 'too-many-files')
    );
    setRejection(tooMany ? 'Drop one file only' : rejectMessage);
  };

  return (
    <Input.Wrapper
      label={label}
      description={description}
      withAsterisk={withAsterisk}
      error={error ?? rejection}
      labelElement="div"
      withBlockChildren
    >
      {file ? (
        <Group className={classes.result} gap="sm" wrap="nowrap">
          {kind === 'image' ? (
            <ImagePreview file={file} />
          ) : (
            <ThemeIcon variant="default" size="lg">
              <IconFile size={18} />
            </ThemeIcon>
          )}
          <div className={classes.texts}>
            <Text size="sm" truncate>
              {file.name}
            </Text>
            <Text size="xs">
              <FileSize value={file.size} />
            </Text>
          </div>
          <ActionIcon
            variant="default"
            size="lg"
            aria-label={`Remove ${file.name}`}
            data-path={dataPath}
            onClick={() => onChange?.(null)}
          >
            <IconTrash size={18} color="var(--mantine-color-red-text)" />
          </ActionIcon>
        </Group>
      ) : (
        <Dropzone
          accept={accept}
          multiple={false}
          maxFiles={1}
          onDrop={handleDrop}
          onReject={handleReject}
          className={classes.dropzone}
          mod={{ invalid: !!(error ?? rejection) }}
          aria-label={`${label}: ${title}`}
          inputProps={{ 'aria-label': `Upload ${label}` }}
          data-path={dataPath}
        >
          <Stack align="center" justify="center" gap={4} className={classes.empty}>
            {kind === 'image' ? <IconPhoto size={32} /> : <IconUpload size={32} />}
            <Text size="sm">{title}</Text>
            <Text size="xs">{hint}</Text>
          </Stack>
        </Dropzone>
      )}
    </Input.Wrapper>
  );
}

import { useState } from 'react';
import { Combobox, InputBase, Pill, PillsInput, useModal } from '@mantine/core';
import { useFormField } from '@mantine/hooks';
import type { ReferenceModel } from '../types';
import { ReferencePicker } from './ReferencePicker';

interface ReferenceInputProps {
  label: string;
  description?: string;
  withAsterisk?: boolean;
  targetModel: ReferenceModel | null;
  multiple: boolean;
  value?: string[];
  onChange?: (value: string[]) => void;
  error?: React.ReactNode;
  'data-path'?: string;
}

const OPEN_KEYS = ['Enter', ' ', 'ArrowDown'];

export function ReferenceInput({
  label,
  description,
  withAsterisk,
  targetModel,
  multiple,
  value,
  onChange,
  error,
  'data-path': dataPath,
}: ReferenceInputProps) {
  const field = useFormField<string[]>(onChange);
  const selected = (field.subscribed ? field.value : value) ?? [];
  // Remounts the picker on every open so its draft starts from the current value
  const [session, setSession] = useState(0);
  const placeholder = multiple ? 'Select entries' : 'Select entry';

  const modal = useModal({
    title: `${placeholder}: ${label}`,
    children: (
      <ReferencePicker
        key={session}
        initialValue={selected}
        targetModel={targetModel}
        multiple={multiple}
        onApply={(keys) => {
          onChange?.(keys);
          modal.close();
        }}
        onCancel={() => modal.close()}
      />
    ),
  });

  const openPicker = () => {
    setSession((current) => current + 1);
    modal.open();
  };

  const removeKey = (key: string) => onChange?.(selected.filter((item) => item !== key));

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Backspace' && selected.length > 0) {
      event.preventDefault();
      removeKey(selected[selected.length - 1]);
    }
    if (OPEN_KEYS.includes(event.key)) {
      event.preventDefault();
      openPicker();
    }
  };

  const wrapperProps = { label, description, withAsterisk, error };
  const fieldProps = {
    readOnly: true,
    pointer: true,
    'aria-haspopup': 'dialog' as const,
    'data-path': dataPath,
    onKeyDown: handleKeyDown,
  };
  const chevron = <Combobox.Chevron error={error} />;

  if (!multiple) {
    return (
      <InputBase
        {...wrapperProps}
        {...fieldProps}
        value={selected[0] ?? ''}
        placeholder={placeholder}
        onClick={openPicker}
        rightSection={chevron}
        rightSectionPointerEvents="none"
      />
    );
  }

  return (
    <PillsInput
      {...wrapperProps}
      pointer
      onClick={openPicker}
      rightSection={chevron}
      rightSectionPointerEvents="none"
    >
      <Pill.Group>
        {selected.map((key) => (
          <Pill
            key={key}
            withRemoveButton
            removeButtonProps={{ 'aria-label': `Remove ${key}` }}
            onRemove={() => removeKey(key)}
          >
            {key}
          </Pill>
        ))}
        <PillsInput.Field
          {...fieldProps}
          placeholder={selected.length === 0 ? placeholder : undefined}
        />
      </Pill.Group>
    </PillsInput>
  );
}

